const body = $input.first().json || {};
const media = Array.isArray(body.data) ? body.data : [];
const now = new Date();
const todayStart = new Date(now);
todayStart.setHours(0, 0, 0, 0);
const yesterdayStart = new Date(todayStart);
yesterdayStart.setDate(yesterdayStart.getDate() - 1);
const tomorrowStart = new Date(todayStart);
tomorrowStart.setDate(tomorrowStart.getDate() + 1);

return media
  .filter(item => {
    if (!item.timestamp) return true;
    const published = new Date(item.timestamp);
    return published >= yesterdayStart && published < tomorrowStart;
  })
  .map(item => ({
    json: {
      instagram_media_id: item.id,
      media: item,
      collected_at: now.toISOString()
    }
  }));

const mediaItem = $('SYS_SplitMediaItems').item.json;
const media = mediaItem.media || {};
const insightsPayload = $('IG_ReadMediaInsights').item.json || {};
const commentsPayload = $input.first().json || {};
const collectedAt = mediaItem.collected_at || new Date().toISOString();

function metricValue(payload, names) {
  const rows = Array.isArray(payload.data) ? payload.data : [];
  for (const name of names) {
    const row = rows.find(item => item.name === name);
    const value = row?.values?.[0]?.value;
    if (value !== undefined && value !== null) return Number(value);
  }
  return null;
}

function cleanText(value) {
  return String(value || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
}

const comments = Array.isArray(commentsPayload.data) ? commentsPayload.data : [];
const normalizedComments = comments.map(comment => ({
  instagram_comment_id: comment.id,
  instagram_media_id: media.id,
  comment_text: cleanText(comment.text),
  author_username: comment.username || null,
  commented_at: comment.timestamp || null,
  like_count: comment.like_count ?? null,
  raw_comment: comment
}));

const stopWords = new Set(['the','and','for','with','you','your','this','that','are','was','как','что','это','для','или','если','меня','только','очень','надо','нужно','без','его','она','они','мы','вы','не','на','в','и','а','но']);
const counts = new Map();
for (const comment of normalizedComments) {
  for (const word of comment.comment_text.toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/)) {
    if (word.length < 4 || stopWords.has(word)) continue;
    counts.set(word, (counts.get(word) || 0) + 1);
  }
}
const repeated = Array.from(counts.entries())
  .filter(([, count]) => count > 1)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([phrase, count]) => ({ phrase, count }));

const metrics = {
  reach: metricValue(insightsPayload, ['reach']),
  views: metricValue(insightsPayload, ['views', 'plays', 'impressions']),
  likes: metricValue(insightsPayload, ['likes']) ?? (media.like_count ?? null),
  comments: metricValue(insightsPayload, ['comments']) ?? (media.comments_count ?? normalizedComments.length),
  saves: metricValue(insightsPayload, ['saved', 'saves']),
  shares: metricValue(insightsPayload, ['shares']),
  total_interactions: metricValue(insightsPayload, ['total_interactions'])
};

const summary = [
  media.media_type || 'unknown media',
  'received ' + (metrics.likes ?? 0) + ' likes',
  (metrics.comments ?? normalizedComments.length) + ' comments',
  metrics.saves === null ? null : metrics.saves + ' saves',
  metrics.reach === null ? null : metrics.reach + ' reach',
  metrics.views === null ? null : metrics.views + ' views'
].filter(Boolean).join(', ') + '.';

return [{
  json: {
    instagram_media_id: media.id,
    media_type: media.media_type || null,
    media_product_type: media.media_product_type || null,
    caption: media.caption || null,
    permalink: media.permalink || null,
    published_at: media.timestamp || null,
    collected_at: collectedAt,
    metrics,
    comments: normalizedComments,
    repeated_phrase_candidates: repeated,
    response_summary: summary,
    raw_media: media,
    raw_insights: insightsPayload
  }
}];

const row = $input.first().json || {};
const top = Array.isArray(row.top_content) ? row.top_content : [];
const under = Array.isArray(row.underperformed) ? row.underperformed : [];
const themes = Array.isArray(row.repeated_themes) ? row.repeated_themes : [];
const env = typeof $env !== 'undefined' ? $env : {};

function n(value) {
  return value === null || value === undefined ? 0 : Number(value);
}

function text(value, max = 80) {
  const clean = String(value || 'untitled').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
  return clean.length > max ? clean.slice(0, max - 3) + '...' : clean;
}

function contentLine(item) {
  return '- ' + text(item.caption || item.permalink || item.instagram_media_id) + ' | score ' + n(item.score) + ' | likes ' + n(item.likes) + ', comments ' + n(item.comments) + ', saves ' + n(item.saves) + ', reach ' + n(item.reach) + ', views ' + n(item.views);
}

const best = top[0];
const worst = under[0];
const themeLine = themes.length ? themes.slice(0, 6).map(item => item.theme + ' (' + item.count + ')').join(', ') : 'not enough repeated comment language';
const bestReason = best ? 'Best performer is driven by ' + [n(best.comments) + ' comments', n(best.saves) + ' saves', n(best.likes) + ' likes'].join(', ') + '.' : 'No best performer yet.';
const underReason = worst ? 'Lowest performer has score ' + n(worst.score) + '; review hook, topic clarity, and CTA.' : 'No underperformer yet.';
const marketSignal = themes.length ? 'Repeated language suggests parent attention around: ' + themeLine + '.' : 'Comment volume is still too low for a stable market signal.';
const nextAction = best ? 'Make the next content action a follow-up post or story that expands the best-performing topic and asks for one concrete parent example.' : 'Publish one clear question-led post and collect the first comment baseline.';

const lines = [
  'BrainCoach Instagram Analytics MVP-1',
  new Date().toISOString(),
  '',
  'Window: yesterday + today',
  '- media collected: ' + n(row.media_count),
  '- likes: ' + n(row.likes),
  '- comments: ' + n(row.comments),
  '- saves: ' + n(row.saves),
  '- reach: ' + n(row.reach),
  '- views: ' + n(row.views),
  '',
  '1. Top content',
  ...(top.length ? top.slice(0, 3).map(contentLine) : ['- none']),
  '',
  '2. What performed best',
  '- ' + bestReason,
  '',
  '3. What underperformed',
  ...(under.length ? under.slice(0, 2).map(contentLine) : ['- none']),
  '- ' + underReason,
  '',
  '4. Repeated comment themes',
  '- ' + themeLine,
  '',
  '5. Possible market signals',
  '- ' + marketSignal,
  '',
  '6. Recommended next content action',
  '- ' + nextAction,
  '',
  'Boundary: read-only Instagram analytics; no autoposting; no auto-replies; storage target bgs_orch.production.'
];

return [{
  json: {
    report_text: lines.join('\n'),
    chat_id: env.BRAINCOACH_TELEGRAM_CHAT_ID || 'REPLACE_WITH_TELEGRAM_CHAT_ID'
  }
}];
